#!/usr/bin/env python3
"""T-32 approach-slices: per-trade features from the trade's wall approach history (T28 cache),
for the local analysis script tools/compute/t32-approach-slices.py (owner request 27.09 via CEO:
"detail the retry-approach breakdown by slices"). Reads:
  tmp-t32/main-trades.csv, tmp-t32/retries-link.csv (wall key already known for linked trades)
  <home>/study/approaches-t28/D20/<day>/approaches-<SYM>.csv  (side=bid rows; approach_index 0-based
     from wall birth; new cache path per Engineer 27.09, old study/approaches/D20 being deleted)
  <home>/study/root-<day>/instruments.csv  (tick_size, qty_step -> wall $ = price_tick*tick_size*size_at_arm*qty_step,
     same formula as tools/compute/t29-wall-filter.py)
  <home>/study/regime/*.csv  (btc_ret_4h_bps per minute, same threshold/gluing as tools/compute/t32-epcap.py)
  <klines_home>/study/klines/ref-<SYM>-1m.csv  (rv_24h, same formula as tools/compute/exit-sim.py rv_24h;
     "quiet" family threshold 262 bps = 0.0262, per docs/plan/HYPOTHESES.md Г-25/Г-26)

Writes tmp-t32/slices-trades.csv: one row per trade in main-trades.csv, with link status + all derived
features (empty for ambiguous/unlinked -- rule "doesn't cut" trades w/o a number, so they must still
appear with an empty approach number).

    python3 slices_features.py
"""
import csv
import glob
import math
import os
import datetime as dt

HOME = os.path.expanduser("~/alpha")
TRADES = os.path.join(HOME, "tmp-t32/main-trades.csv")
LINK = os.path.join(HOME, "tmp-t32/retries-link.csv")
OUT = os.path.join(HOME, "tmp-t32/slices-trades.csv")

MIN_AGE_MS = 45 * 60 * 1000
THRESH_BPS = -44.55
GAP_MS = 30 * 60_000
TAIL_MS = 31 * 60_000
QUIET_RV = 0.0262  # 262 bps (Г-25/Г-26)

CACHE_DIRS = [  # (month, day, approaches-t28 path, root path for instruments.csv, regime path)
    ("aug", os.path.join(HOME, "epochs/e-aug/study/approaches-t28/D20")),
    ("sep", os.path.join(HOME, "epochs/e-archive/study/approaches-t28/D20")),
    ("sep", os.path.join(HOME, "study/approaches-t28/D20")),
]
ROOT_HOMES = [os.path.join(HOME, "epochs/e-aug"), os.path.join(HOME, "epochs/e-archive"), HOME]
REGIME_DIRS = [os.path.join(HOME, "epochs/e-aug/study/regime"), os.path.join(HOME, "epochs/e-archive/study/regime"),
               os.path.join(HOME, "study/regime")]
KLINES_AUG = os.path.join(HOME, "epochs/e-aug/study/klines")
KLINES_SEP = os.path.join(HOME, "study/klines")


def day_of_ms(t_ms):
    return dt.datetime.fromtimestamp(t_ms / 1000, dt.timezone.utc).strftime("%Y-%m-%d")


def load_trades():
    rows = []
    with open(TRADES, newline="", encoding="utf-8") as f:
        for r in csv.DictReader(f):
            r["_t0"] = int(r["t0_ms"])
            r["_day"] = day_of_ms(r["_t0"])
            rows.append(r)
    return rows


def load_link():
    out = {}
    with open(LINK, newline="", encoding="utf-8") as f:
        for r in csv.DictReader(f):
            out[(r["month"], r["sym"], int(r["t0_ms"]))] = r
    return out


def all_days_for(dirs):
    days = []
    for month, d in dirs:
        for day_dir in sorted(glob.glob(os.path.join(d, "20*"))):
            days.append((month, os.path.basename(day_dir), day_dir))
    return days


APPR_DAYS = all_days_for(CACHE_DIRS)


def scan_wall_rows(sym, wall_keys):
    """wall_keys: set of (price_tick_str, birth_ms_str). -> [(arm_ms, age_ms, price_tick, birth_ms, size_at_arm,
    disarm_ms, disarm_reason, approach_index)] across ALL days, side=bid, sorted by arm_ms, per wall."""
    out = {}
    for month, day, path in APPR_DAYS:
        fp = os.path.join(path, f"approaches-{sym}.csv")
        if not os.path.exists(fp):
            continue
        with open(fp, newline="", encoding="utf-8") as f:
            r = csv.DictReader(f)
            for row in r:
                if row["side"] != "bid":
                    continue
                w = (row["price_tick"], row["birth_ms"])
                if w not in wall_keys:
                    continue
                out.setdefault(w, []).append(row)
    for w in out:
        out[w].sort(key=lambda row: int(row["arm_ms"]))
    return out


def load_instruments(day):
    for h in ROOT_HOMES:
        fp = os.path.join(h, "study", f"root-{day}", "instruments.csv")
        if os.path.exists(fp):
            inst = {}
            with open(fp, encoding="utf-8") as f:
                for row in csv.DictReader(l for l in f if not l.startswith("#")):
                    inst[row["symbol"]] = (float(row["tick_size"]), float(row["qty_step"]))
            return inst
    return {}


INST_CACHE = {}


def inst_for(day, sym):
    if day not in INST_CACHE:
        INST_CACHE[day] = load_instruments(day)
    return INST_CACHE[day].get(sym)


def load_regime():
    m = {}
    for d in REGIME_DIRS:
        for f in sorted(glob.glob(os.path.join(d, "20*.csv"))):
            day = os.path.basename(f)[:-4]
            for row in csv.DictReader(open(f, encoding="utf-8")):
                mt = int(row["minute_ms"])
                if dt.datetime.fromtimestamp(mt / 1000, dt.timezone.utc).strftime("%Y-%m-%d") != day:
                    continue
                v = row["btc_ret_4h_bps"]
                m[mt] = float(v) if v not in ("", None) else None
    return m


def build_episodes(regime):
    mins = sorted(regime)
    runs, cur = [], None
    for mt in mins:
        under = regime[mt] is not None and regime[mt] <= THRESH_BPS
        if under:
            cur = [mt, mt] if cur is None else [cur[0], mt]
        else:
            if cur is not None:
                runs.append(tuple(cur))
                cur = None
    if cur is not None:
        runs.append(tuple(cur))
    episodes = []
    for s, e in runs:
        if episodes and s - episodes[-1][1] <= GAP_MS:
            episodes[-1] = (episodes[-1][0], e)
        else:
            episodes.append((s, e))
    return episodes


def assign_episode(t0, episodes):
    for i, (s, e) in enumerate(episodes):
        if s <= t0 <= e + TAIL_MS:
            return i, s
    return None, None


def rv_24h(closes_sorted_keys, closes, m):
    """closes: minute_ms -> close. keys: sorted list of minute_ms. m: minute floor of entry (exclusive upper bound)."""
    import bisect
    lo = bisect.bisect_left(closes_sorted_keys, m - 1440 * 60_000)
    hi = bisect.bisect_left(closes_sorted_keys, m)
    cl = [closes[k] for k in closes_sorted_keys[lo:hi]]
    if len(cl) < 720:
        return None
    s = 0.0
    n = 0
    for a, b in zip(cl, cl[1:]):
        if a > 0 and b > 0:
            s += math.log(b / a) ** 2
            n += 1
    return math.sqrt(s) if n else None


KLINES_CACHE = {}


def klines_for(month, sym):
    key = (month, sym)
    if key in KLINES_CACHE:
        return KLINES_CACHE[key]
    d = KLINES_AUG if month == "aug" else KLINES_SEP
    fp = os.path.join(d, f"ref-{sym}-1m.csv")
    closes = {}
    if os.path.exists(fp):
        with open(fp, encoding="utf-8") as f:
            for row in csv.DictReader(f):
                closes[int(row["minute_ms"])] = float(row["close"])
    keys = sorted(closes)
    KLINES_CACHE[key] = (keys, closes)
    return keys, closes


def main():
    trades = load_trades()
    link = load_link()
    for t in trades:
        t["_link"] = link.get((t["month"], t["sym"], t["_t0"]))

    # wall keys needed, per symbol
    walls_by_sym = {}
    for t in trades:
        lk = t["_link"]
        if lk and lk["status"] == "linked":
            walls_by_sym.setdefault(t["sym"], set()).add((lk["price_tick"], lk["birth_ms"]))

