        runs.append(tuple(cur))
    episodes = []
    for s, e in runs:
        if episodes and s - episodes[-1][1] <= GAP_MS:
            episodes[-1] = (episodes[-1][0], e)
        else:
            episodes.append((s, e))
    return episodes


