               "pnl_usd": t["pnl_usd"], "reason": t["reason"], "status": lk["status"] if lk else "no_link_row"}
        ep_i, ep_s = assign_episode(t["_t0"], episodes)
        m_floor = (t["_t0"] // 60_000) * 60_000
        row["btc_bps_entry"] = regime.get(m_floor)
        row["episode_minute"] = round((t["_t0"] - ep_s) / 60_000, 1) if ep_s is not None else None
        # family
        keys, closes = klines_for(t["month"], t["sym"])
        rv = rv_24h(keys, closes, m_floor)
        row["rv24h"] = round(rv, 5) if rv is not None else None
        row["family"] = ("quiet" if rv <= QUIET_RV else "volatile") if rv is not None else None
        if lk and lk["status"] == "linked":
            w = (lk["price_tick"], lk["birth_ms"])
            wall_rows = wall_rows_by_sym.get(t["sym"], {}).get(w, [])
            entry_i = next((i for i, r in enumerate(wall_rows) if int(r["arm_ms"]) == t["_t0"]), None)
            if entry_i is None:
                n_no_entry_row += 1
                row["approach_number_at_entry"] = lk["approach_number_at_entry"]
            else:
                n_ok += 1
                er = wall_rows[entry_i]
                row["approach_number_at_entry"] = int(er["approach_index"]) + 1
                row["age_ms_entry"] = int(er["age_ms"])
                row["size_at_arm_entry"] = int(er["size_at_arm"])
                inst = inst_for(t["_day"], t["sym"])
                if inst:
                    tick, step = inst
                    row["wall_usd"] = round(int(er["price_tick"]) * tick * int(er["size_at_arm"]) * step, 2)
                row["n_before_45min"] = sum(1 for r in wall_rows[:entry_i] if int(r["age_ms"]) < MIN_AGE_MS)
                aged_upto = [r for r in wall_rows[:entry_i + 1] if int(r["age_ms"]) >= MIN_AGE_MS]
                row["traded_serial_at_entry"] = len(aged_upto)
                if entry_i > 0:
                    pr = wall_rows[entry_i - 1]
                    row["gap_since_prev_ms"] = int(er["arm_ms"]) - int(pr["disarm_ms"]) if pr["disarm_ms"] else None
                    row["prev_disarm_reason"] = pr["disarm_reason"]
                else:
                    row["gap_since_prev_ms"] = None
                    row["prev_disarm_reason"] = "нет (первый подход стены)"
        out_rows.append(row)

    fields = ["month", "sym", "t0_ms", "t1_ms", "pnl_usd", "reason", "status", "approach_number_at_entry",
              "age_ms_entry", "size_at_arm_entry", "wall_usd", "n_before_45min", "traded_serial_at_entry",
              "gap_since_prev_ms", "prev_disarm_reason", "btc_bps_entry", "episode_minute", "rv24h", "family"]
    with open(OUT, "w", newline="", encoding="utf-8") as f:
